"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["35196"],{896481(t){t.exports=JSON.parse('{"id":8766,"title":"\u7535\u5F71\u7EA7\u753B\u9762","description":"\u8BF7\u6839\u636E\u4EE5\u4E0B\u8BBE\u5B9A\u751F\u6210\u7535\u5F71\u7EA7\u753B\u9762\uFF1A\\n[\u4E3B\u4F53\u8BBE\u5B9A]\uFF1A[\u6B64\u5904\u7528\u6237\u9700\u660E\u786E\u4E3B\u4F53\uFF0C\u5982\u5177\u4F53\u7684\u673A\u7532\u578B\u53F7\u3001\u5E9F\u571F\u4E2D\u7684\u7279\u5B9A\u89D2\u8272\u7B49]\\n[\u955C\u5934\u57FA\u7840\u5C5E\u6027]\uFF1A\\n    - [\u955C\u5934\u8FD0\u52A8\u65B9\u5411]\uFF1A\u4ECE\u4EE5\u4E0B\u9009\u62E9\u6216\u7EC4\u5408\uFF0C\u5982\u201C\u7F13\u6162\u5411\u524D\u63A8\u955C\uFF0C\u7126\u70B9\u9010\u6B65\u6536\u7F29\u81F3[\u6838\u5FC3\u4E3B\u4F53\u5177\u4F53\u90E8\u4F4D]\uFF0C\u666F\u522B\u4ECE[\u8D77\u59CB\u666F\u522B]\u8FC7\u6E21\u5230[\u7ED3\u675F\u666F\u522B]\u201D \u3001\u201C\u5300\u901F\u5411\u540E\u62C9\u955C\uFF0C\u666F\u522B\u4ECE\u7279\u5199\u6269\u5C55\u81F3\u5168\u666F\u201D\u7B49\u57FA\u7840\u7EBF\u6027\u8FD0\u52A8\uFF0C\u6216\u201C\u73AF\u7ED5[\u4E3B\u4F53]\u505A360\xb0\u5F27\u5F62\u8FD0\u955C\uFF0C\u4FDD\u6301\u4E2D\u7B49\u666F\u522B\uFF0C\u955C\u5934\u9AD8\u5EA6\u4E0E\u4E3B\u4F53\u80A9\u90E8\u9F50\u5E73\u201D \u3001\u201C\u4ECE\u753B\u9762\u5DE6\u4E0B\u89D2\u659C\u5411\u63A8\u81F3\u53F3\u4E0A\u89D2\uFF0C\u666F\u522B\u4ECE\u8FDC\u666F\u2192\u4E2D\u666F\uFF0C\u8DDF\u968F[\u4E3B\u4F53\u8FD0\u52A8\u8F68\u8FF9]\u201D\u7B49\u590D\u5408\u8FD0\u52A8\u3002\\n    - [\u89C6\u89D2\u5C42\u7EA7]\uFF1A\u9009\u62E9\u5982\u201C90\xb0\u5782\u76F4\u4FEF\u62CD\uFF0C\u9AD8\u7A7A\u4E0A\u5E1D\u89C6\u89D2\uFF0C\u5FFD\u7565\u4E3B\u4F53\u7EC6\u8282\uFF0C\u7A81\u51FA\u5168\u5C40\u5E03\u5C40\u4E0E\u89C4\u6A21\u201D\u7684\u4E0A\u5E1D\u89C6\u89D2\uFF0C\u6216\u201C45\xb0\u9AD8\u673A\u4F4D\u4FEF\u62CD\uFF0C\u955C\u5934\u9AD8\u5EA6\u9AD8\u4E8E\u4E3B\u4F532 - 3\u500D\uFF0C\u666F\u522B\u4E3A\u5168\u666F / \u4E2D\u5168\u666F\u201D\u7684\u4FEF\u89D2\u89C6\u89D2\u7B49\uFF0C\u660E\u786E\u89C6\u89D2\u9AD8\u5EA6\u4E0E\u53D9\u4E8B\u529F\u80FD\u3002\\n    - [\u60C5\u7EEA\u5316\u8FD0\u955C]\uFF1A\u4F9D\u636E\u60C5\u7EEA\u9700\u6C42\u7EC4\u5408\uFF0C\u5982\u201C0.5\u500D\u901F\u5FEB\u901F\u63A8\u955C\uFF0C\u624B\u6301\u955C\u5934\u8F7B\u5FAE\u6296\u52A8\uFF0C\u666F\u522B\u4ECE\u673A\u7532\u7FA4\u5168\u666F\u2192\u4E3B\u70AE\u53D1\u5C04\u53E3\u7279\u5199\uFF0C\u80CC\u666F\u654C\u519B\u6A21\u7CCA\u6210\u865A\u5F71\u201D\u8868\u8FBE\u7D27\u5F20\u6025\u4FC3\uFF0C\u6216\u201C3\u500D\u901F\u6781\u6162\u62C9\u955C\uFF0C\u955C\u5934\u96F6\u6296\u52A8\uFF0C\u4ECE\u727A\u7272\u673A\u7532\u7684\u7834\u635F\u80F8\u53E3\u7279\u5199\u2192\u8352\u539F\u5168\u666F\uFF0C\u5915\u9633\u67D4\u5149\u94FA\u6EE1\u753B\u9762\uFF0C\u5927\u666F\u6DF1\u4FDD\u7559\u8FDC\u5904\u7684\u5E78\u5B58\u8005\u526A\u5F71\u201D\u8425\u9020\u60B2\u58EE\u8083\u7A46\u3002\\n    - [\u7279\u6B8A\u573A\u666F\u9002\u914D]\uFF1A\u9488\u5BF9\u673A\u7532\u53D8\u5F62 / \u542F\u52A8\u573A\u666F\uFF0C\u91C7\u7528\u201C\u6162\u52A8\u4F5C\u63A8\u955C+\u7126\u70B9\u8DDF\u968F\u53D8\u5F62\u8F68\u8FF9+\u5206\u5C42\u865A\u5316\uFF0C\u666F\u522B\u4ECE\u673A\u7532\u6838\u5FC3\u2192\u5168\u8EAB\uFF0C\u53D8\u5F62\u5173\u8282\u5904\u505A\u52A8\u6001\u6A21\u7CCA\u5904\u7406\uFF0C\u955C\u5934\u901F\u5EA6\u4E0E\u53D8\u5F62\u8282\u594F\u540C\u6B65\u201D\uFF1B\u5E9F\u571F\u6076\u52A3\u73AF\u5883\u573A\u666F\u5219\u201C\u624B\u6301\u955C\u5934\u8F7B\u5FAE\u98A0\u7C38+\u4F4E\u89D2\u5EA6\u6A2A\u79FB+\u52A8\u6001\u7C92\u5B50\u7279\u6548\uFF08\u6C99\u5C18/\u9178\u96E8\uFF09\uFF0C\u955C\u5934\u7A7F\u900F\u7C92\u5B50\u7FA4\u8DDF\u968F\u4E3B\u4F53\uFF0C\u524D\u666F\u7C92\u5B50\u865A\u5316\uFF0C\u540E\u666F\u4E3B\u4F53\u6E05\u6670\u201D\uFF1B\u592A\u7A7A / \u5931\u91CD\u573A\u666F\u4F7F\u7528\u201C\u65E0\u91CD\u529B\u6F02\u6D6E\u8FD0\u955C+360\xb0\u81EA\u7531\u65CB\u8F6C+\u96F6\u53C2\u8003\u7CFB\u89C6\u89D2\uFF0C\u955C\u5934\u968F\u673A\u7532\u540C\u6B65\u6F02\u6D6E\uFF0C\u65E0\u660E\u786E\u4E0A\u4E0B\u5DE6\u53F3\uFF0C\u666F\u522B\u5728\u4E2D\u666F\u4E0E\u7279\u5199\u95F4\u7F13\u6162\u5207\u6362\u201D\u3002\\n    - [\u9898\u6750\u98CE\u683C\u9650\u5B9A]\uFF1A\u660E\u786E\u753B\u9762\u98CE\u683C\uFF0C\u5982\u201C\u7535\u5F71\u7EA7\u6697\u8272\u8C03\uFF0C\u9897\u7C92\u611F\u80F6\u7247\u8D28\u611F\u201D\u3002","owner":"\u77E2\u5FD7\u4E0D\u6E1D","upvotes":4,"downvotes":1,"upvoteDifference":3,"updatedAt":"2026-04-13T20:38:51.934Z"}')}}]);